CREATE TABLE IF NOT EXISTS `appointment_co_therapists` (
	`id` int AUTO_INCREMENT NOT NULL,
	`appointmentId` int NOT NULL,
	`therapistUserId` int NOT NULL,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `appointment_co_therapists_id` PRIMARY KEY(`id`)
);
ALTER TABLE `appointments` ADD COLUMN IF NOT EXISTS `isJointSession` boolean DEFAULT false NOT NULL;

